// @ts-nocheck
const METADATA = {
  website: "https://github.com/Fysheep",
  author: "Fyshi",
  name: "Balancer-Variants",
  version: "1.2.0",
  id: "Balancer-Variants.Fyshi",
  description: "A Mod which adds various forms of balancers from 3x1 to 10x1",
  minimumGameVersion: ">=1.5.0",
};

class Mod extends shapez.Mod {
  init() {
    // Compact variant bar: each NxN balancer is shown as a single square tile
    // with its size written on it, instead of a 75-100px wide sprite.
    this.modInterface.registerCss(`
      #ingame_HUD_PlacerVariants .variants .variant.bvCompact .iconWrap {
        width: calc(25px * var(--ui-scale));
        height: calc(25px * var(--ui-scale));
        opacity: 0.35;
      }
      #ingame_HUD_PlacerVariants .variants .variant.bvCompact .bvSize {
        position: absolute;
        inset: 0;
        display: flex;
        align-items: center;
        justify-content: center;
        pointer-events: none;
        color: #fff;
        font-family: GameFont, sans-serif;
        font-weight: 700;
        font-size: calc(11px * var(--ui-scale));
        text-shadow: 0 0 3px #000, 0 0 2px #000;
      }
    `);

    this.modInterface.runAfterMethod(shapez.HUDBuildingPlacer, "rerenderVariants", function () {
      for (const variantEl of this.variantsElement.querySelectorAll(".variant")) {
        const label = variantEl.querySelector(".label");
        const match = label && /^B_Variants_(\d+)$/.exec(label.textContent);
        if (!match) {
          continue;
        }
        variantEl.classList.add("bvCompact");
        const size = document.createElement("div");
        size.className = "bvSize";
        size.textContent = match[1];
        variantEl.appendChild(size);
      }
    });

    for (let i = 3; i <= 10; i++) {
      let _bData = {
        str: `B_Variants_${i}`,
        name: `Balancer ${i}x1`,
        desc: `${i}x1 Balancer`,
      };

      // Declare a new type of item processor
      shapez.enumItemProcessorTypes[_bData.name] = _bData.name;

      // For now, balancers always have the same speed
      shapez.MOD_ITEM_PROCESSOR_SPEEDS[_bData.name] = () => 1000;

      // Declare a handler for the processor so we define the "distribute" operation
      shapez.MOD_ITEM_PROCESSOR_HANDLERS[_bData.name] = function (payload) {
        const ejectorComp = payload.entity.components.ItemEjector;
        const processorComp = payload.entity.components.ItemProcessor;

        const slotsIn = payload.entity.components.ItemAcceptor.slots.length;
        const slotsOut = payload.entity.components.ItemEjector.slots.length;

        for (let j = 0; j < slotsIn; ++j) {
          const item = payload.items.get(j);
          if (!item) {
            continue;
          }

          //Cycle through all EjectorSlots to find the first empty
          for (
            let k = 0;
            !ejectorComp.canEjectOnSlot(
              processorComp.nextOutputSlot % slotsOut
            ) && k < slotsOut;
            ++k
          )
            processorComp.nextOutputSlot++;

          payload.outItems.push({
            item,
            preferredSlot: processorComp.nextOutputSlot++ % slotsOut,
            doNotTrack: true,
          });
        }
        return true;
      };

      shapez.enumBalancerVariants[_bData.str] = _bData.str;

      this.modInterface.addVariantToExistingBuilding(
        shapez.MetaBalancerBuilding,
        shapez.enumBalancerVariants[_bData.str],
        {
          name: _bData.name,
          description: _bData.desc,

          tutorialImageBase64: RESOURCES[`DemoImgBalancer${i}.png`],
          regularSpriteBase64: RESOURCES[`balancer${i}.png`],
          blueprintSpriteBase64: RESOURCES[`BalancerBluePrint${i}.png`],

          dimensions: new shapez.Vector(i, 1),

          isUnlocked(root) {
            return true;
          },
        }
      );

      // Extend instance methods
      this.modInterface.extendClass(shapez.MetaBalancerBuilding, ({ $old }) => ({
        updateVariants(entity, rotationVariant, variant) {
          if (variant === shapez.enumBalancerVariants[_bData.str]) {
            entity.components.ItemProcessor.type = _bData.name;
            entity.components.ItemEjector.setSlots(
              [...Array(i).keys()].map((idx) => ({
                pos: new shapez.Vector(idx, 0),
                direction: shapez.enumDirection.top,
              }))
            );
            entity.components.ItemAcceptor.setSlots(
              [...Array(i).keys()].map((idx) => ({
                pos: new shapez.Vector(idx, 0),
                direction: shapez.enumDirection.bottom,
              }))
            );
            entity.components.BeltUnderlays.underlays = [
              ...[...Array(i).keys()].map((idx) => ({
                pos: new shapez.Vector(idx, 0),
                direction: shapez.enumDirection.top,
              })),
            ];
          } else {
            $old.updateVariants.bind(this)(entity, rotationVariant, variant);
          }
        },
      }));
    }
  }
}
